mapper.select:
SELECT 
  FROM sms03_group_send
 WHERE sms03_group_send_id = #{groupSendId}
   AND sms03_company_id    = #{companyId}

mapper.update:
UPDATE sms03_group_send
   SET sms03_title   = #{req.title},
       sms03_content = #{req.content},
       sms03_note    = #{req.note}
 WHERE sms03_group_send_id = #{req.groupSendId}
   AND sms03_company_id    = #{companyId}

mapper.delete:
